/* ===================== BÀI 18 · LOOP và vòng lặp có điều kiện ===================== */
/* Bài 18 · LOOP và vòng lặp có điều kiện (AMTS-EMB-002-M05-L02, X86-018) — sinh bởi tools/author/mpu8086/l18.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P18=[{"label": "Ví dụ: LOOP in 5 dấu sao", "code": "; Ví dụ 1: LOOP in 5 dấu sao\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     CX, 5                   ; số lần lặp\n        MOV     AH, 02H                 ; hàm in ký tự\n        MOV     DL, '*'\nlap:\n        INT     21H                     ; in '*'\n        LOOP    lap                     ; CX = CX - 1; CX <> 0 thì nhảy\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "CX = 5, thân vòng chỉ có INT 21h (in DL = '*'). LOOP chạy 5 lần: 4 lần nhảy (17 chu kỳ), lần cuối CX về 0 không nhảy (5 chu kỳ). Mã máy E2 FC: độ dời −4 quay về nhãn lap. Đoán trước: ở lần LOOP thứ 5, lệnh có nhảy không? Đáp án: không (CX = 0)."}, {"label": "Ví dụ: đếm phần tử dương bằng LOOP", "code": "; Ví dụ 2: đếm số phần tử dương của mảng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nmang    DB      5, -3, 0, 7, -1, 2\ndem     DB      ?                       ; số phần tử > 0\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 6                   ; số phần tử\n        MOV     SI, 0                   ; chỉ số phần tử\n        MOV     BL, 0                   ; bộ đếm\nxet:\n        CMP     mang[SI], 0             ; so sánh có dấu với 0\n        JLE     bo                      ; <= 0: không đếm\n        INC     BL\nbo:\n        INC     SI\n        LOOP    xet\n        MOV     dem, BL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Mảng 6 byte có dấu 5, −3, 0, 7, −1, 2. CMP mang[SI], 0 rồi JLE (có dấu) bỏ qua phần tử ≤ 0. Đếm trong BL, ghi dem = 3 một lần ở cuối. Xem cột số lần chạy: INC BL chạy 3 lần, LOOP 6 lần. Đoán trước: với phần tử thứ hai (−3), JLE có nhảy không? Đáp án: có."}, {"label": "Lỗi: CX = 0, LOOP chạy 65 536 lần", "code": "; Ví dụ 3: danh sách rỗng (n = 0) mà vẫn LOOP (CÓ LỖI)\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DW      0                       ; số phần tử: danh sách rỗng\nthap    DW      ?                       ; số vòng đã chạy, word thấp\ncao     DW      ?                       ; word cao\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, n                   ; CX = 0\n        XOR     AX, AX                  ; DX:AX đếm số vòng (32 bit)\n        XOR     DX, DX\ndem:\n        ADD     AX, 1\n        ADC     DX, 0\n        LOOP    dem                     ; LỖI: 0 - 1 = FFFFh, lặp tiếp\n        MOV     thap, AX\n        MOV     cao, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: danh sách rỗng, n = 0 nên CX = 0. LOOP giảm CX thành FFFFh rồi nhảy: thân chạy 65 536 lần, DX:AX = 0001 0000h (thap = 0000h, cao = 0001h), tổng khoảng 1,64 triệu chu kỳ. Bấm Chạy và xem cột số lần chạy của LOOP. Sửa: thêm JCXZ trước vòng (Ví dụ 4). Đoán trước: sau lần LOOP đầu tiên, CX bằng bao nhiêu (hệ 16)? Đáp án FFFFh."}, {"label": "Ví dụ: JCXZ chặn vòng lặp rỗng", "code": "; Ví dụ 4: JCXZ chặn vòng lặp khi CX = 0\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nn       DW      0\nthap    DW      ?\ncao     DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, n\n        XOR     AX, AX\n        XOR     DX, DX\n        JCXZ    het                     ; CX = 0: bỏ qua cả vòng lặp\ndem:\n        ADD     AX, 1\n        ADC     DX, 0\n        LOOP    dem\nhet:\n        MOV     thap, AX\n        MOV     cao, DX\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Giống Ví dụ 3 nhưng có JCXZ het trước vòng: CX = 0 nên nhảy thẳng tới het (18 chu kỳ), thân vòng chạy 0 lần, thap = cao = 0. Với n ≥ 1, JCXZ không nhảy (6 chu kỳ) và vòng chạy đúng n lần. Đoán trước: JCXZ có nhảy không? Đáp án: có."}, {"label": "Ví dụ: LOOPNE tìm dấu phẩy", "code": "; Ví dụ 5: LOOPNE tìm dấu phẩy đầu tiên trong chuỗi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'HELLO, 8086'           ; 11 ký tự\nvitri   DB      0FFH                    ; FFh: không thấy\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 11\n        MOV     SI, -1                  ; INC SI đầu vòng đưa về 0\ntim:\n        INC     SI\n        CMP     chuoi[SI], ','\n        LOOPNE  tim                     ; lặp khi CX <> 0 và ZF = 0\n        JNE     het                     ; ZF = 0: hết chuỗi, không thấy\n        MOV     AX, SI\n        MOV     vitri, AL\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Tìm ',' trong 'HELLO, 8086' (11 ký tự). SI = −1 rồi INC SI đầu vòng. Thấy ở SI = 5: CMP đặt ZF = 1 nên LOOPNE thôi lặp dù CX = 5 ≠ 0. JNE không nhảy (ZF = 1), vitri = 5. LOOPNE tốn 19 chu kỳ khi nhảy. Đoán trước: ở lần LOOPNE thứ 6, lệnh có nhảy không? Đáp án: không (ZF = 1)."}, {"label": "Bẫy: kiểm CX sau LOOPNE, sót phần tử cuối", "code": "; Ví dụ 6: tìm 'Z' rồi kiểm CX thay vì ZF\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'ABZ'\nthay    DB      ?                       ; 'C' có, 'K' không\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 3\n        MOV     SI, -1\ntim:\n        INC     SI\n        CMP     chuoi[SI], 'Z'\n        LOOPNE  tim\n        MOV     thay, 'K'               ; MOV không đổi cờ\n        JCXZ    het                     ; BẪY: Z ở cuối chuỗi cũng có CX = 0\n        MOV     thay, 'C'               ; (sửa: JNE het thay cho JCXZ het)\nhet:\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: 'Z' nằm ở phần tử cuối. Vòng dừng với ZF = 1 (thấy) nhưng CX cũng vừa về 0. JCXZ nhảy nên chương trình kết luận 'K' (không có). MOV thay, 'K' không đổi cờ. Sửa: thay JCXZ het bằng JNE het (kiểm ZF). Đoán trước: sau LOOPNE, ZF bằng bao nhiêu? Đáp án 1."}, {"label": "Ví dụ: LOOPE bỏ qua dấu cách đầu dòng", "code": "; Ví dụ 7: LOOPE bỏ qua các dấu cách đầu dòng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ndong    DB      '   42'                 ; 3 dấu cách rồi hai chữ số\ndau     DB      ?                       ; chỉ số ký tự đầu tiên khác ' '\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 5\n        MOV     SI, -1\nbo:\n        INC     SI\n        CMP     dong[SI], ' '\n        LOOPE   bo                      ; lặp khi CX <> 0 và ZF = 1\n        MOV     AX, SI\n        MOV     dau, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "LOOPE lặp khi CX ≠ 0 và ZF = 1, tức “còn ký tự và vẫn là dấu cách”. Ba dấu cách đầu cho ZF = 1; ký tự '4' cho ZF = 0, vòng dừng với SI = 3, CX = 1. dau = 3. Nếu dòng toàn dấu cách, vòng dừng với ZF = 1 và CX = 0: lại phải kiểm ZF. Đoán trước: sau CMP với '4', ZF bằng bao nhiêu? Đáp án 0."}, {"label": "Ví dụ: vòng lồng nhau, cất CX vào BX", "code": "; Ví dụ 8: vòng lồng nhau 3 hàng x 4 cột\n        .MODEL  SMALL\n        .STACK  100H\n        .CODE\nMAIN    PROC\n        MOV     AH, 02H\n        MOV     CX, 3                   ; số hàng\nhang:\n        MOV     BX, CX                  ; cất bộ đếm hàng: LOOP chỉ dùng CX\n        MOV     CX, 4                   ; số cột\n        MOV     DL, '#'\ncot:\n        INT     21H\n        LOOP    cot                     ; vòng trong làm CX về 0\n        MOV     DL, 0DH                 ; về đầu dòng\n        INT     21H\n        MOV     DL, 0AH                 ; xuống dòng\n        INT     21H\n        MOV     CX, BX                  ; lấy lại bộ đếm hàng\n        LOOP    hang\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Vòng ngoài 3 hàng, vòng trong 4 cột. MOV BX, CX cất bộ đếm hàng vì vòng trong dùng CX và làm nó về 0; MOV CX, BX lấy lại trước LOOP hang. In 0Dh (về đầu dòng) và 0Ah (xuống dòng) sau mỗi hàng. Đoán trước: ngay sau LOOP cot cuối cùng của hàng đầu, CX bằng bao nhiêu? Đáp án 0000h."}];
const sim18=makeX86Sim(document.getElementById("x86-l18"),{id:"s18",presets:P18,file:"BAI18.ASM"});
makeX86Ex(document.getElementById("ex-l18"),sim18,[{"t": "Tổng 1 + 2 + … + n", "d": "Đọc một phím chữ số n ('0'–'9') bằng INT 21h hàm 08h. Code mẫu đã đưa n vào CX. Viết tiếp để tính 1 + 2 + … + n bằng LOOP và ghi vào biến tong (word); n = 0 thì tong = 0. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: tổng 1 + 2 + ... + n\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?                       ; 1 + 2 + ... + n (n = 0 thì tong = 0)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = phím '0'..'9'\n        SUB     AL, '0'\n        MOV     CL, AL\n        MOV     CH, 0                   ; CX = n\n        XOR     AX, AX                  ; AX giữ tổng\n; Viết tiếp: cộng n, n - 1, ..., 1 vào AX bằng LOOP\n; (n = 0 thì không lặp), rồi ghi AX vào tong.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "5", "mem": [{"at": "tong", "word": 15}]}, {"in": "0", "mem": [{"at": "tong", "word": 0}]}, {"in": "1", "mem": [{"at": "tong", "word": 1}]}, {"in": "9", "mem": [{"at": "tong", "word": 45}]}, {"in": "3", "mem": [{"at": "tong", "word": 6}]}, {"in": "7", "mem": [{"at": "tong", "word": 28}]}]}, {"t": "Vị trí đầu tiên của ký tự", "d": "Chuỗi 'HOPNGU8086' (10 ký tự, chỉ số 0–9) có sẵn trong biến chuoi. Đọc một phím bằng INT 21h hàm 08h, tìm lần xuất hiện đầu tiên của ký tự đó bằng LOOPNE. Thấy thì ghi chỉ số vào biến vitri và in chỉ số (một chữ số); không thấy thì giữ vitri = FFh và in '-'. Kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: vị trí đầu tiên của một ký tự trong chuỗi\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'HOPNGU8086'            ; 10 ký tự, chỉ số 0..9\nvitri   DB      0FFH                    ; FFh: không có\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = ký tự cần tìm\n        MOV     CX, 10\n        MOV     SI, -1\n; Viết tiếp: tìm bằng LOOPNE; thấy thì ghi chỉ số vào\n; vitri và in chữ số đó, không thấy thì in '-'.\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "H", "out": "0", "mem": [{"at": "vitri", "bytes": [0]}]}, {"in": "6", "out": "9", "mem": [{"at": "vitri", "bytes": [9]}]}, {"in": "8", "out": "6", "mem": [{"at": "vitri", "bytes": [6]}]}, {"in": "X", "out": "-", "mem": [{"at": "vitri", "bytes": [255]}]}, {"in": "G", "out": "4", "mem": [{"at": "vitri", "bytes": [4]}]}, {"in": "h", "out": "-", "mem": [{"at": "vitri", "bytes": [255]}]}]}, {"t": "Đếm ký tự nhanh hơn", "d": "Chuỗi 'ABRACADABRA-8086' (16 ký tự) có sẵn trong biến chuoi. Đọc một phím bằng INT 21h hàm 08h và ghi vào biến dem (1 byte) số lần ký tự đó xuất hiện trong chuỗi. Code mẫu đã đúng nhưng dùng chuoi[BX], đếm thẳng vào ô nhớ và DEC CX/JNZ. Viết lại để đạt cả giới hạn chu kỳ và giới hạn byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: đếm số lần một ký tự xuất hiện trong chuỗi\n; Bản này đúng nhưng chậm: chỉ số chuoi[BX], đếm thẳng\n; vào ô nhớ, DEC CX/JNZ. Hãy viết lại cho nhanh và gọn.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nchuoi   DB      'ABRACADABRA-8086'      ; 16 ký tự\ndem     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = ký tự cần đếm\n        MOV     dem, 0\n        MOV     BX, 0\n        MOV     CX, 16\nxet:\n        CMP     chuoi[BX], AL           ; 9 + EA(9) chu kỳ\n        JNE     tiep\n        INC     dem                     ; 15 + EA(6) chu kỳ\ntiep:\n        INC     BX\n        DEC     CX\n        JNZ     xet\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "A", "mem": [{"at": "dem", "bytes": [5]}]}, {"in": "8", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": "Z", "mem": [{"at": "dem", "bytes": [0]}]}, {"in": "R", "mem": [{"at": "dem", "bytes": [2]}]}, {"in": "6", "mem": [{"at": "dem", "bytes": [1]}]}, {"in": "a", "mem": [{"at": "dem", "bytes": [0]}]}], "perf": {"cycles": 920, "bytes": 36}}]);

makeQuiz("quiz18","score18",[{"q": "<code>MOV CX, 0<\/code> / <code>lap: INC BX<\/code> / <code>LOOP lap<\/code>. Thân vòng (<code>INC BX<\/code>) chạy bao nhiêu lần?", "o": ["0 lần", "65 536 lần", "1 lần", "65 535 lần"], "a": 1, "e": "LOOP kiểm ở cuối: thân chạy, rồi CX = 0 − 1 = FFFFh ≠ 0 nên nhảy; tiếp tục tới khi CX về 0 sau 65 536 lần. Muốn 0 lần phải đặt JCXZ trước vòng."}, {"q": "<code>chuoi DB 'ABCA'<\/code>; <code>MOV CX, 4<\/code> / <code>MOV SI, -1<\/code> / <code>tim: INC SI<\/code> / <code>CMP chuoi[SI], 'C'<\/code> / <code>LOOPNE tim<\/code>. Sau vòng, SI và CX bằng bao nhiêu?", "o": ["SI = 2, CX = 1", "SI = 2, CX = 2", "SI = 3, CX = 0", "SI = 2, CX = 0"], "a": 0, "e": "Ba lần CMP với 'A', 'B', 'C'; mỗi lần LOOPNE giảm CX: 4 → 3 → 2 → 1. Ở 'C', ZF = 1 nên LOOPNE thôi lặp, SI = 2, CX = 1."}, {"q": "Sau một vòng LOOPNE tìm ký tự, cách nào cho biết <b>chắc chắn<\/b> đã thấy ký tự?", "o": ["ZF = 1 (dùng <code>JE thay<\/code>)", "CX ≠ 0 (dùng <code>JCXZ<\/code> để loại)", "SI nhỏ hơn độ dài chuỗi", "CF = 0 sau vòng"], "a": 0, "e": "Ký tự ở phần tử cuối làm vòng dừng với CX = 0 và SI = độ dài − 1, giống trường hợp không thấy. Chỉ ZF (cờ của lần CMP cuối) phân biệt được."}, {"q": "Một vòng lặp chạy 100 lần. Thay <code>DEC CX<\/code> / <code>JNZ lap<\/code> bằng <code>LOOP lap<\/code> tiết kiệm bao nhiêu?", "o": ["1 chu kỳ và 1 byte", "Không tiết kiệm gì", "100 chu kỳ và 1 byte", "1 600 chu kỳ và 2 byte"], "a": 2, "e": "DEC CX/JNZ: 99 × 18 + 6 = 1 788 chu kỳ, 3 byte. LOOP: 99 × 17 + 5 = 1 688 chu kỳ, 2 byte. Chênh 1 chu kỳ mỗi vòng, nhân 100."}, {"q": "<code>MOV CX, 3<\/code> / <code>ngoai: MOV CX, 2<\/code> / <code>trong: NOP<\/code> / <code>LOOP trong<\/code> / <code>LOOP ngoai<\/code>. Chuyện gì xảy ra?", "o": ["Thân NOP chạy đúng 6 lần rồi dừng", "Thân NOP chạy đúng 2 lần rồi dừng", "Vòng ngoài không bao giờ dừng", "Trình dịch báo lỗi hai LOOP lồng nhau"], "a": 2, "e": "Vòng trong trả CX = 0; LOOP ngoài giảm thành FFFFh (≠ 0) nên nhảy về ngoai, lại đặt CX = 2: không bao giờ thoát. Phải cất CX của vòng ngoài (MOV BX, CX … MOV CX, BX)."}]);

